```java
@Component
public class SecurityMetrics {

    private final Counter idorAttempts;
    private final Counter authzFailures;
    private final Timer invoiceAccessDuration;

    public SecurityMetrics(MeterRegistry registry) {
        this.idorAttempts = Counter.builder("idor.attempts.total")
            .description("Total IDOR attack attempts detected")
            .tags("severity", "high")
            .register(registry);

        this.authzFailures = Counter.builder("authorization.failures.total")
            .description("Total authorization check failures")
            .tag("type", "cross_account")
            .register(registry);

        this.invoiceAccessDuration = Timer.builder("invoice.access.duration")
            .description("Time to complete authorization check")
            .register(registry);
    }

    public void recordIdorAttempt() {
        idorAttempts.increment();
    }

    public void recordAuthzFailure() {
        authzFailures.increment();
    }
}
```

